function solve(n, trust) {
  const score = new Array(n + 1).fill(0);
  for (const [a, b] of trust) { score[a]--; score[b]++; }
  for (let i = 1; i <= n; i++) if (score[i] === n - 1) return i;
  return -1;
}

function solve(n, trust) {
  const inD = new Array(n + 1).fill(0), outD = new Array(n + 1).fill(0);
  for (const [a, b] of trust) { outD[a]++; inD[b]++; }
  for (let i = 1; i <= n; i++) if (inD[i] === n - 1 && outD[i] === 0) return i;
  return -1;
}

